describe('Print Filtered Table View', () => {
  beforeEach(() => {
    cy.visit('/table');
    cy.get('[data-testid="table-container"]').should('be.visible');
  });

  it('should print filtered table with applied filters', () => {
    // Apply filters
    cy.get('[data-testid="filter-status"]').click();
    cy.get('[data-testid="filter-option-active"]').click();

    cy.get('[data-testid="filter-department"]').click();
    cy.get('[data-testid="filter-option-engineering"]').click();

    // Verify filters are applied
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="active-filter-badge"]').should('contain', 'Active');
    cy.get('[data-testid="active-filter-badge"]').should('contain', 'Engineering');

    // Click print button
    cy.get('[data-testid="print-button"]').click();

    // Verify print dialog opens
    cy.window().then((win) => {
      cy.stub(win, 'print');
    });

    cy.get('[data-testid="print-button"]').click();
    cy.window().its('print').should('have.been.called');

    // Verify filtered data is in print preview
    cy.get('[data-testid="print-preview"]').should('be.visible');
    cy.get('[data-testid="print-preview"] [data-testid="table-row"]').each(($row) => {
      cy.wrap($row).should('contain', 'Active');
      cy.wrap($row).should('contain', 'Engineering');
    });
  });

  it('should print table with multiple filters and pagination', () => {
    // Apply multiple filters
    cy.get('[data-testid="filter-status"]').click();
    cy.get('[data-testid="filter-option-inactive"]').click();

    cy.get('[data-testid="filter-date-range"]').click();
    cy.get('[data-testid="date-picker-start"]').type('01/01/2024');
    cy.get('[data-testid="date-picker-end"]').type('12/31/2024');
    cy.get('[data-testid="date-range-apply"]').click();

    // Navigate to second page
    cy.get('[data-testid="pagination-next"]').click();
    cy.get('[data-testid="current-page"]').should('contain', '2');

    // Open print dialog
    cy.get('[data-testid="print-button"]').click();

    // Verify print preview shows all filtered data across pages
    cy.get('[data-testid="print-preview"]').should('be.visible');
    cy.get('[data-testid="print-preview-page-count"]').should('contain', 'Page');

    // Verify print settings are available
    cy.get('[data-testid="print-settings"]').should('be.visible');
    cy.get('[data-testid="print-orientation-landscape"]').should('exist');
    cy.get('[data-testid="print-include-headers"]').should('be.checked');

    // Confirm print
    cy.get('[data-testid="confirm-print"]').click();

    cy.window().then((win) => {
      cy.stub(win, 'print');
    });

    cy.window().its('print').should('have.been.called');
  });

  it('should handle print with no filters applied', () => {
    // Ensure no filters are applied
    cy.get('[data-testid="clear-all-filters"]').click();
    cy.get('[data-testid="active-filter-badge"]').should('not.exist');

    // Click print button
    cy.get('[data-testid="print-button"]').click();

    // Verify print dialog opens with all data
    cy.get('[data-testid="print-preview"]').should('be.visible');
    cy.get('[data-testid="print-preview"] [data-testid="table-row"]').should('have.length.greaterThan', 0);

    // Verify confirmation message
    cy.get('[data-testid="print-info-message"]').should('contain', 'printing all records');

    cy.get('[data-testid="confirm-print"]').click();
  });

  it('should cancel print operation', () => {
    // Apply a filter
    cy.get('[data-testid="filter-status"]').click();
    cy.get('[data-testid="filter-option-active"]').click();

    // Open print dialog
    cy.get('[data-testid="print-button"]').click();
    cy.get('[data-testid="print-preview"]').should('be.visible');

    // Cancel print
    cy.get('[data-testid="cancel-print"]').click();

    // Verify print dialog is closed
    cy.get('[data-testid="print-preview"]').should('not.exist');

    // Verify table is still visible with filters applied
    cy.get('[data-testid="table-container"]').should('be.visible');
    cy.get('[data-testid="active-filter-badge"]').should('contain', 'Active');
  });

  it('should export filtered table as PDF', () => {
    // Apply filters
    cy.get('[data-testid="filter-status"]').click();
    cy.get('[data-testid="filter-option-active"]').click();

    // Open print menu
    cy.get('[data-testid="print-button"]').click();
    cy.get('[data-testid="print-preview"]').should('be.visible');

    // Select PDF export option
    cy.get('[data-testid="export-format-pdf"]').click();

    // Verify PDF settings appear
    cy.get('[data-testid="pdf-settings"]').should('be.visible');
    cy.get('[data-testid="pdf-filename"]').should('have.value', 'table-export');

    // Confirm export
    cy.get('[data-testid="confirm-export"]').click();

    // Verify download is triggered
    cy.readFile('cypress/downloads/table-export.pdf').should('exist');
  });
});
